/* course16.js — Course 16 content (DNS and names in the network; loaded on demand via course-core.js) */
/* ============================================================
   COURSE 16 — DNS and names in the network (from name to address, local DNS, public DNS
   and the path from the root, record types, when DNS lies). Follows the basic explanation of
   DNS in the course <i>Why networks exist and how data travels</i> and DNS spoofing/tunneling from the course <i>Advanced security (DPI, IDS/IPS)</i>.
   Scene c16Net: PC — DNS (resolver) — NET — {ROOT/TLD, AUTH, WEB, ATTACKER}.
   ============================================================ */
var C16R={pc:[64,124],res:[196,124],net:[330,124],root:[452,50],auth:[452,198],web:[576,124],evil:[196,198]};
function c16Net(pfx){
  return '<svg id="'+pfx+'svg" viewBox="0 0 640 272" width="100%" style="display:block">'
    +'<line x1="79" y1="124" x2="181" y2="124" style="stroke:var(--line2);stroke-width:1.6"/>'
    +'<line x1="211" y1="124" x2="315" y2="124" style="stroke:var(--line2);stroke-width:1.6"/>'
    +'<line x1="343" y1="116" x2="439" y2="58" style="stroke:var(--line2);stroke-width:1.6"/>'
    +'<line x1="343" y1="132" x2="439" y2="190" style="stroke:var(--line2);stroke-width:1.6"/>'
    +'<line x1="345" y1="124" x2="561" y2="124" style="stroke:var(--line2);stroke-width:1.6"/>'
    +'<line x1="317" y1="131" x2="209" y2="191" style="stroke:var(--line2);stroke-width:1.6"/>'
    +'<g id="'+pfx+'glow"></g>'
    +csHost(64,124,'desktop','--green','PC')
    +csHost(196,124,'dns','--blue','DNS')
    +csHost(330,124,'globe','--cyan','NET')
    +csHost(452,50,'cloud','--violet','ROOT/TLD')
    +csHost(452,198,'dns','--violet','AUTH')
    +csHost(576,124,'server','--green','WEB')
    +csHost(196,198,'shield','--red','ATTACKER')
    +'<g id="'+pfx+'dyn"></g></svg>';
}
function c16P(pfx,intro,terms){
  return '<p style="color:var(--muted);font-size:var(--crs-fs,13.5px);line-height:1.55;margin:0 0 10px">'+intro+'</p>'
    +'<div class="osi-stage">'+c16Net(pfx)+'</div><div class="m1-cap" id="'+pfx+'cap"></div>'
    +courseStepControls(pfx)+abbrBox(terms);
}
function c16Mount(pfx,STEPS){
  function show(i){var g=$(pfx+'glow');if(g)g.innerHTML=STEPS[i].glow||'';var d=$(pfx+'dyn');if(d)d.innerHTML=STEPS[i].dyn||'';var c=$(pfx+'cap');if(c)c.innerHTML='<span>'+STEPS[i].cap+'</span>';}
  courseStepper(pfx,STEPS.length,show);
}
function c16g(name,color){var p=C16R[name];return csGlow(p[0],p[1],color,20);}
function c16lbl(x,y,tx,c){return '<text x="'+x+'" y="'+y+'" text-anchor="middle" style="font:700 7.5px var(--mono);fill:var('+c+')">'+esc(tx)+'</text>';}
function c16pkt(path,color,dur){return '<rect x="-6" y="-4" width="12" height="9" rx="2" style="fill:var('+color+')"><animateMotion path="'+path+'" dur="'+(dur||'1.4s')+'" repeatCount="indefinite"/></rect>';}

/* ---------- L1M1 — Why names ---------- */
function renderC16WhyNames(){return c16P('q16a',
  'In the course <i>Why networks exist and how data travels</i> you saw that <b>DNS</b> is the “internet’s phone book”: you type <span class="mono">example.com</span> and DNS returns a number, an <b>IP address</b>. This course goes further – it shows <b>who</b> actually gives that answer, where they get it, and what happens when they get it wrong. We start with a question almost nobody asks out loud: why do we use names at all? The answer “so people can remember them” is only half the truth. The other, more important half: <b>addresses change, names stay</b>. A server moves to another provider and gets a new IP address, a company swaps hardware, a service splits across ten machines in five countries – and you still type the same name. If browsers, links, configurations and emails held hard-coded numbers, every such move would mean visiting <b>all</b> those machines and rewriting the numbers. A name therefore works as a <b>layer of distance</b> between what you remember and where the service physically sits right now. You see the whole thing on the scene: your <b>PC</b> knows the name, <b>DNS</b> knows the name↔address pair, and <b>WEB</b> has some address that may well change tomorrow. Try it in the simulator too: every <b>host</b> (PC, server…) has a <b>DNS name (FQDN)</b> field in its detail, on the <b>Type & services</b> tab – and you will then be able to find it under that name in the <b>path test</b> (the test panel next to the canvas), where by-name targets appear in the <b>“By name (DNS)”</b> group. Filling in the name alone is not enough, though – something has to <b>serve</b> that name, namely a DNS server holding it in its records. You will build exactly that in lesson 2.',
  [['DNS','the service that translates names (web.acme.local) into IP addresses – the network’s “phone book”.'],['FQDN','the full name of a device including its domain, e.g. web.acme.local; in the simulator the “DNS name (FQDN)” field.'],['a layer of distance','the name stays the same even when the address beneath it changes – so the service can move.']]);}
function mountC16WhyNames(){c16Mount('q16a',[
  {glow:c16g('pc','--green'),dyn:c16lbl(160,90,'a human remembers a name, not a number','--green'),cap:'You type a <b>name</b> into the browser – <span class="mono">web.acme.local</span>. You would never remember a number, nor read it out to a colleague on the phone.'},
  {glow:c16g('web','--amber'),dyn:c16lbl(500,264,'the server gets a new address…','--amber'),cap:'But one day the server moves and gets a <b>different IP address</b>. In a network’s life that happens routinely.'},
  {glow:c16g('res','--blue')+c16g('net','--blue')+c16g('web','--blue'),dyn:c16pkt('M 196 124 L 330 124 L 576 124','--blue')+c16lbl(330,264,'…only one record in DNS changes','--blue'),cap:'Only a <b>single DNS record</b> needs fixing. The name stays the same – no user has to rewrite anything.'},
  {glow:c16g('pc','--cyan')+c16g('res','--cyan')+c16g('web','--cyan'),dyn:c16pkt('M 64 124 L 196 124','--cyan')+c16lbl(160,264,'the name = a layer of distance','--cyan'),cap:'The name is a <b>layer of distance</b> between you and where the service physically sits. In the simulator you set it in the <b>DNS name (FQDN)</b> field.'}
]);}
/* ---------- L1M2 — Who asks whom ---------- */
function renderC16Roles(){return c16P('q16b',
  'the course <i>Why networks exist and how data travels</i> drew DNS as <b>one box</b> that simply knows the answer. In reality every name resolution has <b>three roles</b>, and the difference between them is the core of this whole course. <b>1) The client</b> – your computer. It knows the least: it can ask one question (“what IP belongs to this name?”) and wait for a finished answer. It handles nothing else. <b>2) The resolver</b> – the server the client asks. It is usually a DNS server in your network or at your provider. The resolver generally does <b>not know</b> the answer – but it can <b>find it out</b>: it walks the other servers on your behalf and returns the result. It is a kind of errand runner. <b>3) The authoritative server</b> – the one that actually <b>owns</b> the answer. It holds the records for its domain because somebody put them there. When it says “web.acme.local is 10.0.2.20”, that is a definition, not a guess. This difference is worth taking seriously: <b>the authority KNOWS the answer, the resolver only FINDS IT OUT</b>. You could ask the authority directly, but you would have to know which authority it is – and that is exactly the work the resolver does for you. In the simulator the role shows up in the network settings as <b>“DNS server for this network”</b>: clients on that network ask precisely that one. And the resolver role does not have to be played by a server – a <b>router, firewall or L3 switch</b> can take it too. You will see exactly how in the next lesson, in the module “Who resolves? The router as a resolver”.',
  [['the client','your computer: it asks one question and waits for a finished answer; it walks nowhere itself.'],['the resolver','the server the client asks; it usually does not know the answer but finds it out for you from others.'],['the authoritative server','it holds the records for its domain – its answer is a definition, not a guess.']]);}
function mountC16Roles(){c16Mount('q16b',[
  {glow:c16g('pc','--green')+c16g('res','--green'),dyn:c16pkt('M 64 124 L 196 124','--amber')+c16lbl(160,90,'client: web.acme.local = ?','--amber'),cap:'The <b>client</b> can do one thing: ask “what IP belongs to this name?” and wait for a finished answer.'},
  {glow:c16g('res','--blue'),dyn:c16lbl(160,264,'resolver: does not know, but finds out','--blue'),cap:'It asks the <b>resolver</b>. The resolver usually does <b>not know</b> the answer – its job is to <b>find it out</b> for you from other servers.'},
  {glow:c16g('res','--violet')+c16g('net','--violet')+c16g('auth','--violet'),dyn:c16pkt('M 196 124 L 330 124 L 452 198','--violet')+c16lbl(500,264,'authority: owns the record, KNOWS it','--violet'),cap:'The resolver reaches the <b>authoritative server</b> – the one that <b>owns</b> the record. Its answer is a definition, not a guess.'},
  {glow:c16g('pc','--cyan')+c16g('res','--cyan'),dyn:c16pkt('M 196 124 L 64 124','--cyan')+c16lbl(160,264,'the resolver returns the finished result','--cyan'),cap:'The resolver returns the finished result to the client. In the simulator you set this role on a network as the <b>“DNS server for this network”</b>.'}
]);}
/* ---------- L1M3 — Cache and TTL ---------- */
function renderC16Cache(){return c16P('q16c',
  'If the resolver walked the world on <b>every</b> query, the internet would be unbearably slow – opening a single page asks for dozens of names. So every link in the chain <b>caches</b> answers: the client in its system and its browser, and above all the resolver on behalf of all its users at once. Then when anyone asks for the same name, the answer comes <b>instantly from memory</b>, without a single query going out. That is why opening a page a second time is noticeably faster than the first. But an answer in memory <b>ages</b>: what if the address has changed in the meantime? So that a cache never gets stuck on a permanent lie, <b>every</b> DNS answer carries a number with it – the <b>TTL</b> (time to live): how many seconds that answer may be kept before it must be discarded and looked up again. The TTL is set by <b>whoever owns the record</b> – that is, the authority. And it is an interesting choice between two annoyances. A <b>long TTL</b> (say a day) = few queries, fast answers, but a change takes <b>a whole day</b> to spread through the world. A <b>short TTL</b> (say a minute) = a change is almost immediate, but the servers get far more queries. Remember the practical consequence: <b>when you change a record, the change does not take effect at once</b> – part of the world will see it only after the TTL expires. That is why the TTL is lowered first, and only then is the server moved. Once you have built your own DNS in lesson 2, try it in the simulator. Run the same by-name test <b>twice in a row from the same device</b>. The second time you will see “from the client’s local cache” – the client did not even ask the resolver. Now the same name from a <b>different</b> device: it does ask, but gets “from the resolver cache”. Those are exactly the two cache levels. (The remaining <b>TTL</b> on each record shows in advanced mode – the <b>Simple / Advanced</b> toggle is at the top of the app.) What a device remembers is shown in its detail on the <b>DNS cache</b> tab – and you can flush it by hand (the classic helpdesk step). In advanced mode you’ll notice the client remembers <b>“does not exist”</b> too (negative caching) and the time left on each entry. Note that the cache here is a teaching simplification – it is emptied as soon as you change anything in the topology, so your edit to a record takes effect immediately (the real world would have to wait for the TTL).',
  [['the cache','briefly stored DNS answers at the client and the resolver – that is why a second visit is fast.'],['TTL','the answer’s time to live in seconds: how long it may sit in a cache before being looked up again.'],['change propagation','a record change reaches the world only after the TTL expires – so the TTL is lowered before a move.']]);}
function mountC16Cache(){c16Mount('q16c',[
  {glow:c16g('pc','--amber')+c16g('res','--amber')+c16g('net','--amber')+c16g('auth','--amber'),dyn:c16pkt('M 64 124 L 330 124 L 452 198','--amber')+c16lbl(330,264,'first query: the resolver must go out','--amber'),cap:'The <b>first</b> query for a name costs time: the resolver must walk the world and only then find the answer.'},
  {glow:c16g('res','--blue'),dyn:c16lbl(160,264,'answer + TTL stored in the cache','--blue'),cap:'The resolver stores the answer in its <b>cache</b>, along with a <b>TTL</b>: how many seconds it may be kept.'},
  {glow:c16g('pc','--green')+c16g('res','--green'),dyn:c16pkt('M 64 124 L 196 124','--green','0.7s')+c16lbl(160,90,'second query: from memory (fast)','--green'),cap:'The <b>second</b> query for the same name returns <b>instantly from the cache</b> – nothing travels out. That is why a second visit is fast.'},
  {glow:c16g('res','--red')+c16g('web','--red'),dyn:c16lbl(500,264,'a change lands only after the TTL expires ⚠','--red'),cap:'The price of speed: when you <b>change</b> the address, part of the world sees it only after the TTL expires. So the TTL is lowered before a move.'}
]);}
/* ---------- L2M1 — Why have DNS at home and at the company ---------- */
function renderC16WhyLocal(){return c16P('q16d',
  'So far this sounded as if DNS were an internet thing. It is not – <b>your own DNS server</b> makes enormous sense inside a company or a home too, for three reasons. <b>1) Names for your own servers.</b> Your printer, file server and internal applications are not in any public DNS and never will be – nobody outside the company is meant to meet them. Yet you still want to type <span class="mono">web.acme.local</span> instead of <span class="mono">10.0.2.20</span>. Your own DNS lets you: you simply write the records into it yourself. <b>2) Independence and speed.</b> An internal name resolves at home, in milliseconds, without anyone outside learning about it. And with the resolver standing in your own network, users find answers to everyday names already in its cache. <b>3) Visibility and control.</b> The resolver sees what your network is asking about – a golden source both for troubleshooting and for security (in the course <i>Advanced security (DPI, IDS/IPS)</i>, Advanced security, you saw that odd DNS queries can betray a tunnel or malware). For this luxury you pay one price, covered at the end of this lesson: the resolver becomes a <b>critical</b> device. Build it in the simulator: add a <b>Server</b> from the palette and in its detail (Type & services) turn on the <b>DNS (port 53)</b> service – DNS is a service, not a device type of its own. That unlocks a new <b>DNS</b> tab on the server with the editor of <b>records (name → IP address)</b>; fill them in by hand or click <b>“Fill from device names”</b>. It also learns website addresses: a web server (with port 80/443 on) carries them on its own <b>Web</b> tab, so one web server can serve several addresses. Finally, in the client network settings choose that server as the <b>“DNS server for this network”</b> – without this step no name in the network resolves at all, because the clients have nobody to ask (and the topology check flags a network with no resolver). From then on the path test lets you pick a destination under <b>“By name (DNS)”</b>.',
  [['local DNS','your own DNS server in your network: it holds your devices’ names and answers your clients.'],['an internal name','a name that exists only inside the company (web.acme.local) – nobody finds it in public DNS.'],['DNS server (simulator)','a palette server with the DNS service on (port 53); it holds name → device records and a network picks it as its resolver.']]);}
function mountC16WhyLocal(){c16Mount('q16d',[
  {glow:c16g('res','--blue')+c16g('web','--blue'),dyn:c16lbl(330,264,'own record: web.acme.local → WEB','--blue'),cap:'<b>Names for your own servers</b>: your printer and internal site are in no public DNS. Into your own DNS you write them yourself.'},
  {glow:c16g('pc','--green')+c16g('res','--green'),dyn:c16pkt('M 64 124 L 196 124','--green','0.7s')+c16lbl(160,90,'an internal name resolves at home, at once','--green'),cap:'<b>Independence and speed</b>: an internal name resolves at home, in milliseconds, and nobody outside needs to know about it.'},
  {glow:c16g('res','--violet'),dyn:c16lbl(160,264,'the resolver sees what the network asks','--violet'),cap:'<b>Visibility and control</b>: the resolver sees what your network asks about – gold for troubleshooting and security (the course <i>Advanced security (DPI, IDS/IPS)</i> – Advanced security).'},
  {glow:c16g('pc','--cyan')+c16g('res','--cyan')+c16g('net','--cyan')+c16g('web','--cyan'),dyn:c16pkt('M 64 124 L 576 124','--cyan')+c16lbl(500,264,'then the name works in the path test too','--cyan'),cap:'In the simulator: add a <b>DNS server</b>, fill in records (or use <b>“Fill from device names”</b>) and set the network’s <b>“DNS server for this network”</b>.'}
]);}
/* ---------- L2M2 — Records and forwarding ---------- */
function renderC16Forward(){return c16P('q16e',
  'So your company resolver has your own servers’ names written in it. But what happens when somebody asks it for <span class="mono">example.com</span> – a name nobody wrote into its records? The answer is a simple two-sentence rule: <b>what I know, I answer – what I do not know, I pass on</b>. That passing on is called <b>forwarding</b>. The resolver hands the query for a foreign name to another server (typically the provider’s resolver or a public one), waits for the answer, caches it and returns it to the client. The client notices nothing – it asked once and got an answer. The second option is more interesting: <b>turn forwarding off</b>. Then the resolver answers an unknown name with “no such name exists” – abbreviated <b>NXDOMAIN</b> (that is how the simulator reports it; a real resolver that refuses to ask further would rather answer “I refuse” – REFUSED, see the glossary). That sounds like a fault, but it is a legitimate choice: in a strictly separated network (say the OT environment from the course <i>OT/ICS: industrial network security</i>, OT/ICS: industrial network security) you <b>do not want</b> anything inside asking outside; a resolver that knows only your own names is a feature there, not a bug. The simulator has exactly this switch (in <b>advanced mode</b>): the server’s <b>DNS</b> tab has <b>“Forward unknown names out (to the internet)”</b>. In simple mode the switch is hidden and the value comes from the topology – so a preset or a task may have it turned off. On = a name I do not know gets forwarded out. Off = I answer that no such name exists. Try both – and notice that when the resolver wants to forward but <b>cannot get out</b> (say a firewall stops it), the ending is the same: the name does not resolve.',
  [['forwarding','the resolver hands a query for a name it does not know to another server and returns the answer.'],['NXDOMAIN','the answer “no such name exists” – that is what the simulator reports too when the resolver does not know the name and cannot or will not ask further. (To be pedantic: only the authority for that zone may answer this, because only it really knows the name does not exist. A resolver that simply will not ask would in reality answer “I refuse” – REFUSED.)']]);}
function mountC16Forward(){c16Mount('q16e',[
  {glow:c16g('pc','--green')+c16g('res','--green'),dyn:c16pkt('M 196 124 L 64 124','--green','0.7s')+c16lbl(160,90,'what I know → I answer myself','--green'),cap:'Rule, sentence one: a name I have <b>in my records</b> I answer myself, at once.'},
  {glow:c16g('pc','--amber')+c16g('res','--amber'),dyn:c16pkt('M 64 124 L 196 124','--amber')+c16lbl(160,264,'a foreign name: example.com = ?','--amber'),cap:'But now somebody asks for <span class="mono">example.com</span> – a name nobody wrote into my records.'},
  {glow:c16g('res','--blue')+c16g('net','--blue')+c16g('auth','--blue'),dyn:c16pkt('M 196 124 L 330 124 L 452 198','--blue')+c16lbl(500,264,'forwarding: what I do not know, I pass on','--blue'),cap:'Sentence two: <b>forwarding</b>. I pass the query on, wait for the answer, cache it and return it. The client notices nothing.'},
  {glow:c16g('res','--red'),dyn:c16lbl(160,264,'forwarding off → NXDOMAIN','--red'),cap:'With forwarding <b>off</b> I answer <b>NXDOMAIN</b> – “no such name exists”. In a strictly separated network that is a feature, not a bug.'}
]);}
/* ---------- L2M4 (position 3) — Who resolves? The router as resolver ---------- */
var C16RR={pc:[64,124],rtr:[196,124],isp:[452,50],web:[452,198]};
function c16rNet(pfx){
  return '<svg id="'+pfx+'svg" viewBox="0 0 640 272" width="100%" style="display:block">'
    +'<line x1="79" y1="124" x2="182" y2="124" style="stroke:var(--line2);stroke-width:1.6"/>'
    +'<line x1="210" y1="120" x2="438" y2="54" style="stroke:var(--line2);stroke-width:1.6"/>'
    +'<line x1="210" y1="128" x2="438" y2="194" style="stroke:var(--line2);stroke-width:1.6"/>'
    +'<g id="'+pfx+'glow"></g>'
    +csHost(64,124,'desktop','--green','PC')
    +csDev(196,124,'router','RTR')
    +csHost(452,50,'cloud','--violet','ISP DNS')
    +csHost(452,198,'server','--green','WEB')
    +'<g id="'+pfx+'dyn"></g></svg>';
}
function c16rg(name,color){var p=C16RR[name];return csGlow(p[0],p[1],color,20);}
function renderC16RtrDns(){
  return '<p style="color:var(--muted);font-size:var(--crs-fs,13.5px);line-height:1.55;margin:0 0 10px">'
    +'So far we drew the resolver role as a <b>standalone DNS server</b>. But recall your home: no server stands there – and names still resolve. Who does it? <b>The router.</b> A home router is the typical <b>forwarder</b>: it has no records of its own, it just <b>relays</b> the clients’ queries onward to the provider’s resolver (the upstream), caches the answers and returns them. To the clients it is the resolver – whoever really does the resolving for it is called the <b>upstream</b>. A company network usually differs: there the resolver role is played by a <b>full DNS server</b> with its own records (as you built in this lesson’s first module) – because no upstream knows, or should know, internal names like <span class="mono">web.acme.local</span>. When to pick which? In a small network, feel free to keep the role right on the router; once you want to back the resolver up or load it harder, a standalone server pays off. The boundary between the two roles is exactly this:<b>a forwarder knows nothing and passes everything on; a server owns its answers</b>. In the simulator you try both in <b>advanced mode</b>: a router, firewall or L3 switch has a <b>DNS</b> tab in its detail with the <b>“DNS role”</b> choice – <i>forwarder (relays queries onward)</i> with an <b>“Upstream DNS server”</b> picker (with no selection the queries go out to the internet, exactly like a home router), or <i>DNS server (own records)</i> with the same record editor you know from a server. Then just pick the router in the network settings as the <b>“DNS server for this network”</b>. And the last piece of the puzzle: the resolver need not be the same for everyone. In advanced mode a <b>specific device can have its own DNS server</b> (an override in its network settings) – it then asks elsewhere than the rest of the network. Handy for testing, but remember it as a troubleshooter too: “it works for everyone but him” can mean that one machine asks a <b>different resolver</b> than the others.'
    +'</p><div class="osi-stage">'+c16rNet('q16r')+'</div><div class="m1-cap" id="q16rcap"></div>'
    +courseStepControls('q16r')
    +abbrBox([['forwarder','a resolver without records of its own: it just relays queries to an upstream and caches answers – typically a home router.'],['upstream','the server a forwarder relays queries to – the one that really does the resolving (say the provider’s DNS).'],['a per-device DNS override','a specific device can ask a different resolver than the rest of the network (advanced mode) – a troubleshooting trap.']]);}
function mountC16RtrDns(){c16Mount('q16r',[
  {glow:c16rg('pc','--green')+c16rg('rtr','--green'),dyn:c16pkt('M 64 124 L 196 124','--amber')+c16lbl(130,90,'the client asks the router: web = ?','--amber'),cap:'No DNS server stands at home – the client asks <b>the router</b>. To the clients it is the resolver.'},
  {glow:c16rg('rtr','--blue')+c16rg('isp','--blue'),dyn:c16pkt('M 196 124 L 452 50','--blue')+c16lbl(296,252,'forwarder: no records of its own, relays to the upstream','--blue'),cap:'A home router is a <b>forwarder</b>: it knows nothing itself, it <b>relays</b> the query to the upstream (the provider’s DNS), caches the answer and returns it.'},
  {glow:c16rg('rtr','--cyan')+c16rg('pc','--cyan'),dyn:c16pkt('M 196 124 L 64 124','--cyan','0.8s')+c16lbl(330,264,'DNS server: web.acme.local → 10.0.2.20 (own record)','--cyan'),cap:'The other role: a <b>DNS server with its own records</b> – a company router or firewall answers an internal name <b>itself</b>, no upstream needs to know it. In advanced mode: the <b>DNS</b> tab → <b>“DNS role”</b>.'},
  {glow:c16rg('pc','--violet'),dyn:c16lbl(130,90,'override: this device asks elsewhere','--violet'),cap:'And beware: a specific device can have <b>its own DNS server</b> (an override, advanced mode). “Works for everyone but him” then means: it asks a <b>different resolver</b>.'}
]);}
/* ---------- L2M3 — When DNS goes down ---------- */
function renderC16Down(){return c16P('q16f',
  'And now the price of that convenience. When a whole company has one resolver and it <b>fails</b> – or clients simply cannot reach it – you get the situation every helpdesk knows and that makes no sense at first glance: <b>the network is up, but nothing works</b>. The web server runs. The firewall passes what it should. A ping to the address goes through. And yet nothing opens in the browser, because the browser <b>never learns where to connect</b>. The server is healthy, only nobody finds it. Beware the trap almost every beginner falls into: <b>the DNS server need not be broken</b> for this to happen. It is enough that the query does not reach it – a firewall blocks UDP port 53, a link drops, a network gets a misconfigured resolver. From the client’s view the result is identical. Luckily there is a <b>diagnostic trick</b> worth remembering for life: try the same destination <b>by name</b> and then <b>by address</b>. If it works by address but not by name, the fault is <b>not in the network</b> – it is in DNS. And beware: a single resolver holds name resolution for the whole network – leave it alone and the <b>topology check</b> flags it as a single point of failure (SPOF), so double it up: add a second DNS server and pick it as the <b>Backup DNS server</b> in the network settings – the client asks it when the primary can’t be reached (down or blocked port 53) – and once the primary answers again, clients return to it; the backup serves only for the duration of the outage. Try it: <b>power off</b> the primary (right-click) and the name still resolves “via the backup DNS server”. A DNS outage also shows in the <b>Live traffic simulation</b>: flows going by name never even start without resolution, and the log reads “name did not resolve (DNS)”. Try exactly this in the task <b>“The network is fine, nothing works (DNS)”</b>: in the path test pick the destination <span class="mono">web.acme.local</span> under <b>“By name (DNS)”</b> (resolution fails) and then the same target as the device <b>Web</b> by address (it passes). You will see the difference with your own eyes. And the design lesson? The resolver is a <b>critical device</b> – it deserves the same care as the gateway: two servers, so one may fail (the course <i>Network resilience and scaling</i> – Network resilience and scaling).',
  [['the network is up, nothing works','the server runs and answers on its address, but the name does not resolve – the browser has no target.'],['name vs address test','works by address but not by name? The fault is in DNS, not the network. The fastest diagnosis there is.'],['the resolver as a SPOF','a single resolver downs everything even with the network up – so it gets doubled like a gateway (the course <i>Network resilience and scaling</i> – Network resilience and scaling).']])
  +courseCTA('q16fTask','Double up the resolver yourself – open the task “DNS with no backup – add a backup DNS server”.','Open the task');}
function mountC16Down(){c16Mount('q16f',[
  {glow:c16g('pc','--green')+c16g('res','--green')+c16g('net','--green')+c16g('web','--green'),dyn:c16pkt('M 64 124 L 576 124','--green')+c16lbl(500,264,'the server runs, by address it passes ✓','--green'),cap:'Starting point: <b>the server runs</b> and traffic to its address passes normally. Nothing is wrong with the network.'},
  {glow:c16g('res','--red'),dyn:c16lbl(160,264,'the DNS query (UDP 53) never arrives ⚠','--red'),cap:'But the query to the resolver <b>does not arrive</b> – a firewall blocks UDP 53, a link dropped or the resolver is dead. To the client it is all the same.'},
  {glow:c16g('pc','--red'),dyn:c16lbl(160,90,'name does not resolve → the browser goes nowhere','--red'),cap:'The result: <b>the network is up, but nothing works</b>. The server is healthy, only nobody finds it – the browser never learns where to connect.'},
  {glow:c16g('pc','--cyan')+c16g('res','--cyan')+c16g('net','--cyan')+c16g('web','--cyan'),dyn:c16pkt('M 64 124 L 576 124','--cyan')+c16lbl(330,264,'trick: name NO, address YES → DNS is at fault','--cyan'),cap:'A trick for life: works <b>by address</b> but not <b>by name</b>? DNS is at fault, not the network. Try the task <b>“The network is fine, nothing works (DNS)”</b>.'}
]);
  var b=$('q16fTask');if(b)b.onclick=function(){courseTry('dns-backup');};
}
/* ---------- L3M1 — Name hierarchy ---------- */
function renderC16Hierarchy(){return c16P('q16g',
  'So far we moved at home, where you invent names yourself. Out on the internet, though, it could not work for everyone to register whatever they wanted – names would collide. So the public name space is a <b>hierarchical tree</b>, and one unusual rule applies to it: <b>a name reads right to left</b>. Take <span class="mono">www.example.com</span>. At the far right sits (invisibly) the <b>root</b> – the top of the whole tree and the shared beginning of every name in the world; “invisibly” because it is never written in an everyday name (formally it is the empty end after the last dot). Below it is <span class="mono">com</span>, a <b>TLD</b> (top-level domain; such as <span class="mono">com</span>, <span class="mono">cz</span>, <span class="mono">org</span>). Below that is <span class="mono">example</span> – the <b>domain</b> somebody registered and has owned ever since. And only at the far left is <span class="mono">www</span> – a specific name <b>inside</b> that domain, decided solely by its owner. That hierarchy is not for show: it solves two things at once. <b>Uniqueness</b> – there can be only one <span class="mono">example.com</span> in the world, because names are handed out from the top down. And <b>division of labor</b> (technically <b>delegation</b>) – the root does not care about billions of names, it only says “for <span class="mono">com</span>, ask over there”; <span class="mono">com</span> does not care about domain contents, it only says “<span class="mono">example.com</span> is run by that server”. Each floor knows just <b>one step</b> and hands the rest downward. How you walk that tree is the next module.',
  [['the root','the invisible top of the name tree – the shared beginning of all names; it only knows where to find a TLD.'],['TLD','a top-level domain (com, cz, org) – the second floor of the tree, right under the root.'],['delegation','each floor knows only one step down and hands the rest lower – so the tree carries billions of names.']]);}
function mountC16Hierarchy(){
  var name=function(hi){var cells=[['www','--green'],['example','--blue'],['com','--cyan'],['. (root)','--violet']];var w=[54,78,54,72];var o='<g transform="translate(150,232)">';var x=0;cells.forEach(function(c,i){var on=hi===i;o+='<rect x="'+x+'" y="0" width="'+w[i]+'" height="20" rx="3" style="fill:var('+(on?c[1]:'--panel2')+');fill-opacity:'+(on?'.25':'1')+';stroke:var('+(on?c[1]:'--line2')+');stroke-width:'+(on?'1.6':'1')+'"/><text x="'+(x+w[i]/2)+'" y="13" text-anchor="middle" style="font:700 7px var(--mono);fill:var('+(on?c[1]:'--muted')+')">'+esc(c[0])+'</text>';x+=w[i];});return o+'</g>';};
  c16Mount('q16g',[
  {glow:c16g('root','--violet'),dyn:name(3)+c16lbl(500,264,'a name reads right to left: root is rightmost','--violet'),cap:'An unusual rule: <b>a name reads right to left</b>. At the far right sits (invisibly) the <b>root</b> – the top of the tree of all names.'},
  {glow:c16g('root','--cyan'),dyn:name(2)+c16lbl(330,264,'under the root: TLDs (com, cz, org)','--cyan'),cap:'Under the root sits a <b>TLD</b> – a top-level domain, such as <span class="mono">com</span>, <span class="mono">cz</span> or <span class="mono">org</span>.'},
  {glow:c16g('auth','--blue'),dyn:name(1)+c16lbl(500,264,'the domain example.com: it has an owner','--blue'),cap:'Under the TLD sits the <b>domain</b> (<span class="mono">example</span>) – somebody registered it and decides its contents alone ever since.'},
  {glow:c16g('root','--green')+c16g('auth','--green')+c16g('web','--green'),dyn:name(0)+c16lbl(330,264,'delegation: each floor knows one step down','--green'),cap:'At the left is a specific name <b>inside</b> the domain (<span class="mono">www</span>). The tree gives <b>uniqueness</b> and <b>delegation</b>: each floor knows one step down.'}
]);}
/* ---------- L3M2 — Recursion in practice ---------- */
function renderC16Recursion(){return c16P('q16h',
  'Now we join it up: the <b>three roles</b> from lesson 1 and the <b>tree</b> from the last module. The client asks the resolver one question and waits. The resolver has <b>no</b> answer in its cache and nobody to forward to – so it sets out itself and <b>walks the tree from the top down</b>. This is called <b>recursion</b> (a recursive query): the client asks once, the resolver asks as many times as needed. It looks like this. <b>1)</b> The resolver asks the <b>root</b>: “where is <span class="mono">www.example.com</span>?” The root does not know the answer and does not care – it returns a <b>referral</b>: “for <span class="mono">com</span>, ask these servers.” <b>2)</b> The resolver asks the <b>TLD</b> server for <span class="mono">com</span>. It does not know the answer either, but it knows one step more: “the domain <span class="mono">example.com</span> is run by these <b>authoritative</b> servers.” <b>3)</b> The resolver asks the <b>authority</b> – and it alone <b>owns</b> the answer: “<span class="mono">www.example.com</span> is 203.0.113.10.” <b>4)</b> The resolver caches the result and sends it to the client. Notice two things. First: none of the three lied or guessed – <b>each said only what it knows</b>, and that is always either a referral one floor down or a finished answer. Second: all of this happens only on the <b>first</b> query. The root’s and TLD’s answers have long TTLs, so the resolver has the tree’s floors cached long since and in practice usually goes <b>straight to the authority</b>. That “walk around the world” is thus the exception, not the rule.',
  [['recursion','the client asks once, the resolver walks root, TLD and authority for it and returns a finished result.'],['a referral','the answer “I do not know, ask over there one floor down” – how the root and TLD reply.']]);}
function mountC16Recursion(){c16Mount('q16h',[
  {glow:c16g('pc','--green')+c16g('res','--green'),dyn:c16pkt('M 64 124 L 196 124','--green')+c16lbl(160,90,'the client asks ONCE and waits','--green'),cap:'The client asks <b>one</b> question and waits. That a world tour hides behind it does not concern it – that is <b>recursion</b>.'},
  {glow:c16g('res','--violet')+c16g('net','--violet')+c16g('root','--violet'),dyn:c16pkt('M 196 124 L 330 124 L 452 50','--violet')+c16lbl(500,264,'root: “for com, ask over there”','--violet'),cap:'<b>1) The root</b>: does not know the answer, returns a <b>referral</b> – “for <span class="mono">com</span>, ask these servers”.'},
  {glow:c16g('res','--blue')+c16g('root','--blue')+c16g('net','--blue')+c16g('auth','--blue'),dyn:c16pkt('M 452 50 L 330 124 L 196 124','--blue')+c16pkt('M 196 124 L 330 124 L 452 198','--blue')+c16lbl(330,264,'TLD com: “example.com is run by this authority”','--blue'),cap:'<b>2) The TLD</b> <span class="mono">com</span>: also does not know, but knows one step more – “<span class="mono">example.com</span> is run by these <b>authoritative</b> servers”.'},
  {glow:c16g('auth','--cyan')+c16g('net','--cyan')+c16g('res','--cyan')+c16g('pc','--cyan'),dyn:c16pkt('M 452 198 L 330 124 L 64 124','--cyan')+c16lbl(160,264,'authority answers, resolver caches and returns','--cyan'),cap:'<b>3) The authority</b> <b>owns</b> the answer and gives it. <b>4)</b> The resolver caches it and returns it. The same name is then answered straight from the cache – and other names in this domain go straight to the authority.'}
]);}
/* ---------- L3M3 — Public resolvers and privacy ---------- */
function renderC16Public(){return c16P('q16i',
  'So who is your resolver when you have none of your own? By default the one your <b>internet provider</b> assigns – at home automatically over DHCP. But there is a second option: <b>public resolvers</b>, which anyone in the world may use for free. The best known deliberately have memorable addresses: <span class="mono">8.8.8.8</span> (Google) and <span class="mono">1.1.1.1</span> (Cloudflare). They tempt you by being fast, reliable and by answering even where the provider’s resolver misbehaves or censors some names. But before you set one, think this course through to its conclusion. A resolver <b>sees every query</b> you send it – that is, <b>the list of all names your network asks about</b>. That is an extraordinarily telling record: which sites you read, which bank you use, which apps run in the background and at what hour. Remember it this way: <b>whoever is your resolver sees what you ask</b>. Choosing a public resolver is therefore not “better or worse” – it is <b>choosing who gets that list</b>: your provider, a large company on the other side of the world, or (with your own resolver) yourself. And one more reason to take it seriously: queries are classically <b>unencrypted</b>, so anyone along the path sees them too – and the answer can be forged. Both are the last lesson’s topic. A practical recommendation for a company: run <b>your own resolver</b> for internal names and let it <b>forward</b> the rest to one deliberately chosen server outside. The best of both worlds: your own names at home, and one place where you can see and set whom you trust.',
  [['a public resolver','a resolver open to anyone, with a memorable address (8.8.8.8, 1.1.1.1); fast and reliable.'],['DNS privacy','whoever is your resolver sees the list of every name you ask about – a very telling record.']]);}
function mountC16Public(){c16Mount('q16i',[
  {glow:c16g('pc','--green')+c16g('res','--green')+c16g('net','--green'),dyn:c16pkt('M 64 124 L 330 124','--green')+c16lbl(330,264,'default: the provider’s resolver','--green'),cap:'By default your resolver is the one your <b>internet provider</b> assigns – at home automatically over DHCP.'},
  {glow:c16g('net','--blue'),dyn:c16lbl(330,264,'public resolvers: 8.8.8.8, 1.1.1.1','--blue'),cap:'The other option: <b>public resolvers</b> with memorable addresses – <span class="mono">8.8.8.8</span>, <span class="mono">1.1.1.1</span>. They tend to be fast and reliable.'},
  {glow:c16g('pc','--amber')+c16g('res','--amber'),dyn:c16pkt('M 64 124 L 196 124','--amber','0.8s')+c16lbl(160,90,'the resolver sees every query you make','--amber'),cap:'The catch: <b>whoever is your resolver sees what you ask</b> – which sites you read, which bank you use, what runs in the background.'},
  {glow:c16g('res','--cyan')+c16g('net','--cyan'),dyn:c16pkt('M 196 124 L 330 124','--cyan')+c16lbl(330,264,'company: own resolver + a deliberate forward','--cyan'),cap:'A recommendation for a company: <b>your own resolver</b> for internal names, forwarding the rest to one deliberately chosen server outside.'}
]);}
/* ---------- L4M1 — A and AAAA ---------- */
function renderC16A(){return c16P('q16j',
  'The whole course we spoke of “a record” as if there were only one kind. There is not – DNS is not just a list of addresses, it is a <b>small database about a domain</b>, and every row in it has a <b>type</b>. The type says <b>what you are actually asking about</b>: you can ask one domain for its website’s address, for where to deliver its mail, or for who runs it – and get a different answer each time. The most important and most common type is <b>A</b>: the pair <b>name → IPv4 address</b>. This is the record we have been drawing all along, and it is by far the most common type of query in the world. It looks plain: <span class="mono">web.acme.local → 10.0.2.20</span>. Its twin is <b>AAAA</b> (read “quad A”): the same, but <b>name → IPv6 address</b>. Why that name? An IPv6 address is four times longer than an IPv4 one – hence four letters. Good to know: a name can have <b>both</b> records at once, and a modern computer picks for itself which protocol version to connect with (usually it tries both and uses whichever answers first). And one more thing beginners rarely expect: one name can have <b>several A records</b> with different addresses. The server then answers with them in turn and traffic gets roughly split across several machines – the cheapest (and dumbest) kind of load balancing, because unlike the load balancer from the course <i>Network resilience and scaling</i> (Network resilience and scaling), DNS <b>has no idea</b> whether those machines are still alive. In the simulator a <b>name → device</b> record is exactly an A record (rotating several addresses for one name is not something this model does – two A records with the same name will always return the first) – in the DNS server’s detail you enter it directly in simple mode (name → target); <b>in advanced mode</b> you also get a <b>type</b> dropdown and a <b>TTL</b> on each row (the “Fill from device names” button creates A records – and MX ones for mail servers). Let me flag the boundary up front so the next modules do not surprise you: <b>A, CNAME</b> (from the next module) <b>and MX</b> (from the mail module) can actually be tried out. The simulator has no TXT, NS or PTR – for those the explanation stays theory, but you still need to know them, because you will meet them in a real domain right away.',
  [['A','name → IPv4 address. The most common record type; in the simulator it is the “name → device” record.'],['AAAA','name → IPv6 address (“quad A”). A name can have both A and AAAA and the client picks.'],['multiple A records','one name, several addresses – dumb load spreading: DNS has no idea whether the targets are alive.']]);}
function mountC16A(){c16Mount('q16j',[
  {glow:c16g('res','--blue')+c16g('net','--blue')+c16g('web','--blue'),dyn:c16pkt('M 196 124 L 576 124','--blue')+c16lbl(500,264,'A: web.acme.local → 10.0.2.20','--blue'),cap:'<b>A</b> is the pair <b>name → IPv4 address</b> – the record we drew all along. Nine out of ten queries go for it.'},
  {glow:c16g('web','--violet'),dyn:c16lbl(500,264,'AAAA: the same, but an IPv6 address','--violet'),cap:'<b>AAAA</b> (“quad A”) is the same for <b>IPv6</b>. Four letters because an IPv6 address is four times longer than an IPv4 one.'},
  {glow:c16g('pc','--green')+c16g('res','--green')+c16g('net','--green')+c16g('web','--green'),dyn:c16pkt('M 64 124 L 576 124','--green')+c16lbl(330,264,'a name can have A and AAAA – the client picks','--green'),cap:'A name can have <b>both</b> records at once. A modern computer tries both protocol versions and uses whichever answers first.'},
  {glow:c16g('res','--amber')+c16g('web','--amber')+c16g('auth','--amber'),dyn:c16lbl(160,264,'several A records = dumb load spreading','--amber'),cap:'One name can have <b>several A records</b>. Traffic gets roughly split – but DNS has no idea if those machines live (unlike an LB, the course <i>Network resilience and scaling</i> – Network resilience and scaling).'}
]);}
/* ---------- L4M2 — CNAME ---------- */
function renderC16Cname(){return c16P('q16k',
  'The second type you will meet constantly is <b>CNAME</b> – an <b>alias</b> (canonical name). It points not at an address but at <b>another name</b>: “<span class="mono">shop.example.com</span> is really <span class="mono">web.example.com</span> – go ask for that instead”. That extra query is then made by the <b>resolver</b>, which returns both at once – the client does not ask a second time. It sounds like a pointless detour, but it solves one specific pain: <b>a single source of truth</b>. Imagine five names on one server – <span class="mono">shop</span>, <span class="mono">blog</span>, <span class="mono">intranet</span>, <span class="mono">wiki</span> and <span class="mono">www</span>. Make each an <b>A record</b> with an address and, when the server moves, you will be rewriting <b>five</b> addresses and are sure to forget one. Make them <b>CNAMEs</b> to a single name that has the A record, and a move means changing <b>one</b> number in <b>one</b> place. CNAME is therefore used massively where you do not and cannot know the address: cloud services and CDNs tell you “point a CNAME at us”, because they change their addresses as they please. Two things worth knowing. <b>Chaining</b>: a CNAME may point at a name that is itself a CNAME – but each link means another query, so a long chain slows things down and adds places to break (and must never form a loop). And a <b>restriction</b>: a name that has a CNAME generally <b>may not carry other records</b> – which is why you classically cannot put a CNAME on a domain’s root (<span class="mono">example.com</span> without <span class="mono">www</span>), you need an A there. Try it: in the DNS server’s detail, <b>in advanced mode</b>, switch a record’s type to <b>CNAME</b> and give it a target <b>name</b> instead of a device. A by-name test will then show you the whole alias path. Try making the chain loop, too – the simulator spots it and tells you (so does a real resolver).',
  [['CNAME','an alias: the name points not at an address but at another name – which the client then asks for.'],['a single source of truth','five names as CNAMEs to one name with an A record = a move changes one number, not five.'],['CNAME chaining','a CNAME may point at another CNAME, but each link is another query – and it must never loop.']]);}
function mountC16Cname(){c16Mount('q16k',[
  {glow:c16g('pc','--amber')+c16g('res','--amber'),dyn:c16pkt('M 64 124 L 196 124','--amber')+c16lbl(160,90,'shop.example.com = ?','--amber'),cap:'The client asks for <span class="mono">shop.example.com</span>. It expects an address – but this name has no address of its own.'},
  {glow:c16g('res','--violet'),dyn:c16lbl(160,264,'CNAME: “I am really web.example.com”','--violet'),cap:'The answer is a <b>CNAME</b> – an <b>alias</b>: “<span class="mono">shop</span> is really <span class="mono">web.example.com</span>, go ask for that”.'},
  {glow:c16g('res','--blue')+c16g('net','--blue')+c16g('web','--blue'),dyn:c16pkt('M 196 124 L 576 124','--blue')+c16lbl(500,264,'second query: the A record → an address','--blue'),cap:'So the resolver asks again – and <b>only that</b> name has the <b>A record</b> with the address. The alias moved it one query on.'},
  {glow:c16g('web','--green')+c16g('res','--green'),dyn:c16lbl(330,264,'five names, one place to change the address','--green'),cap:'The point: <b>a single source of truth</b>. Five names as CNAMEs to one name with an A record = a move changes <b>one</b> number, not five.'}
]);}
/* ---------- L4M3 — MX and TXT ---------- */
function renderC16MxTxt(){return c16P('q16l',
  'Now two types that together hold up e-mail. When you write a message to <span class="mono">someone@example.com</span>, where does your mail server deliver it? It cannot use the website’s address – the site and the mail may well sit on entirely different machines. So there is <b>MX</b> (mail exchanger): the record that says, about a domain, <b>where to deliver mail</b>. The sending server asks for the MX of <span class="mono">example.com</span>, gets a mail server’s name, resolves that to an address (with an A record – see how the types compose) and only then connects there. There can be several MX records and each has a <b>priority</b> – a number where <b>lower means preferred</b>. That is simple redundancy: when the main server does not answer, mail goes to the backup. <b>You can try MX in the simulator too</b>: a server with a mail service (port 25/143) has a <b>Mail</b> tab where you enter a domain; DNS learns it as an MX record via “Fill from device names”, and in the test you pick the <b>“Mail for domain (MX)”</b> target – you’ll see which mail server it points to. One boundary up front, though: <b>the simulator has no priorities</b> – an MX here points straight at a device, so a second MX as a backup cannot be tried out and stays theory. <b>TXT</b>, by contrast, is simply <b>free text</b> at a domain, where the owner may write whatever they like. It sounds pointless, but two indispensable things grew out of it. <b>Domain ownership verification</b>: a service tells you “add this random string to your TXT” and then checks it. If it is there, you have proven you <b>really control</b> the domain – because only its owner can write into its DNS. And <b>SPF</b>: a TXT record in which the owner <b>lists the servers allowed to send mail in their name</b>. The recipient then checks whether the message came from a permitted server – and if not, it is most likely a forgery. The best part is the idea: here DNS turned from a mere list of addresses into <b>the place where a domain’s owner publicly declares the rules</b> about that domain.',
  [['MX','where to deliver a domain’s mail. Several MX records have priorities – a lower number is preferred.'],['TXT','free text at a domain; it carries services’ verification strings and rules such as SPF.'],['SPF','a TXT record where the owner lists the servers allowed to send mail in their name.']]);}
function mountC16MxTxt(){c16Mount('q16l',[
  {glow:c16g('pc','--amber')+c16g('res','--amber')+c16g('net','--amber')+c16g('auth','--amber'),dyn:c16pkt('M 64 124 L 330 124 L 452 198','--amber')+c16lbl(500,264,'MX: where to deliver mail for example.com?','--amber'),cap:'You write to <span class="mono">someone@example.com</span>. Deliver where? The website’s address will not do – mail sits elsewhere. That is what <b>MX</b> is for.'},
  {glow:c16g('auth','--blue')+c16g('net','--blue')+c16g('web','--blue'),dyn:c16pkt('M 452 198 L 330 124 L 576 124','--blue')+c16lbl(330,264,'several MX have priorities: lower = preferred','--blue'),cap:'MX returns the mail server’s <b>name</b> – which the sender resolves with an A record. Several MX records have <b>priorities</b>: lower is preferred, the rest are backup.'},
  {glow:c16g('auth','--violet'),dyn:c16lbl(500,264,'TXT: domain check via a random string','--violet'),cap:'<b>TXT</b> is free text at a domain. It serves for <b>ownership verification</b>: write a random string there – only the domain owner can.'},
  {glow:c16g('auth','--green')+c16g('net','--green'),dyn:c16lbl(330,264,'SPF in TXT: who may send my mail','--green'),cap:'And <b>SPF</b>: a TXT where the owner lists the <b>servers allowed to send mail in their name</b>. A message from elsewhere is most likely a forgery.'}
]);}
/* ---------- L4M4 — NS and PTR ---------- */
function renderC16NsPtr(){return c16P('q16m',
  'The last two types close the picture. <b>NS</b> (name server) is the record that says: <b>this part of the name space is run by this server</b>. It is exactly the <b>delegation</b> from lesson 3, written as a database row: the <span class="mono">com</span> TLD has an NS record that, asked about <span class="mono">example.com</span>, returns the names of that domain’s authoritative servers. So the referrals a resolver follows during recursion are no magic – they are NS records. Companies use them internally too: “the whole <span class="mono">production.acme.local</span> branch is handled by another server”. <b>PTR</b> (pointer) goes the other way: <b>IP address → name</b>. A reverse lookup. You ask “who is 203.0.113.10?” and get a name. Two cautions: a PTR is maintained <b>separately</b> from the A record (it does not appear automatically) and it is set by <b>whoever owns the address</b> – usually the provider, not the name’s owner. So a PTR cannot be relied on as proof. What is it for then? First, for <b>logs and diagnostics</b>: in an incident record, <span class="mono">mail.example.com</span> is incomparably more readable than a bare number. And second, far more practically, for <b>antispam</b>: mail servers routinely reject messages from machines lacking a sensible PTR matching the name they introduce themselves with. The logic is nicely plain – only someone who <b>really controls</b> the address can set its PTR, so it is a cheap but effective sieve against randomly infected computers spewing spam.',
  [['NS','says which server runs a given part of the names – delegation as a record; the referrals during recursion.'],['PTR','a reverse lookup, IP address → name; maintained separately and set by the address’s owner.'],['PTR in antispam','mail servers reject machines without a sensible PTR – only whoever controls the address can set it.']]);}
function mountC16NsPtr(){c16Mount('q16m',[
  {glow:c16g('root','--violet')+c16g('net','--violet')+c16g('auth','--violet'),dyn:c16pkt('M 452 50 L 330 124 L 452 198','--violet')+c16lbl(500,264,'NS: this domain is run by this server','--violet'),cap:'<b>NS</b> says <b>which server runs a given part of the names</b>. The referrals a resolver follows during recursion are no magic – they are NS records.'},
  {glow:c16g('auth','--blue')+c16g('res','--blue'),dyn:c16lbl(330,264,'inside a company too: another server runs a branch','--blue'),cap:'Companies delegate internally too: “the whole <span class="mono">production.acme.local</span> branch is handled by another server”. That splits the work.'},
  {glow:c16g('web','--amber')+c16g('net','--amber')+c16g('res','--amber'),dyn:c16pkt('M 576 124 L 196 124','--amber')+c16lbl(500,264,'PTR: who is 203.0.113.10? → a name','--amber'),cap:'<b>PTR</b> goes the other way: <b>address → name</b>. It is maintained separately from the A record and set by whoever owns the <b>address</b> – usually the provider.'},
  {glow:c16g('net','--green')+c16g('auth','--green'),dyn:c16lbl(330,264,'PTR: readable logs and a spam sieve','--green'),cap:'What for: <b>logs</b> (a name reads better than a number) and <b>antispam</b> – mail rejects a machine without a sensible PTR.'}
]);}
/* ---------- L5M1 — The forged resolver ---------- */
function renderC16Rogue(){return c16P('q16n',
  'The last lesson takes everything you know and turns it inside out. The whole course rested on one unspoken assumption: that <b>the resolver tells the truth</b>. What if it does not? A client has no way to verify the answer – it simply gets one and connects where it was told. So whoever controls the resolver <b>decides where your connection goes</b>, without touching a single router or cable. This is called a <b>rogue DNS</b>. The attacker either slips you a resolver (say via a fake DHCP or Wi-Fi from the course <i>Wi-Fi: security in depth</i>, Wi-Fi: security in depth) or takes over yours. Then it answers the name <span class="mono">web.acme.local</span> with <b>its own address</b> – and you connect to it in perfectly good faith. The most frightening part is how <b>quiet</b> it is: neither the network nor the firewall sees anything odd. From their point of view the connection is completely normal – right protocol, right port, an allowed rule. It just points somewhere else than you thought. The technical name for this attack is <b>DNS hijacking</b> (a rogue resolver): what defines it is that the attacker <b>controls the resolver</b>. Forging a single answer in transit is something else – that is called <b>DNS spoofing</b> and comes right in the next module. The course <i>Advanced security (DPI, IDS/IPS)</i> showed the opposite problem, a tunnel hidden <i>inside</i> DNS traffic; here it is DNS itself that lies. Here you see <b>why</b> it works: a DNS answer is classically unencrypted and unsigned, so truth cannot be told apart from invention. What saves you? The <b>HTTPS certificate.</b> The attacker’s server may look like the real one, but it has no <b>valid certificate for that name</b> – and the browser screams. That is why you never click through a certificate warning. Try it in the task <b>“Rogue DNS”</b>: the network is configured with the attacker’s resolver, pick the name as the test’s destination and look at what it pointed to.',
  [['a rogue DNS','a resolver the attacker controls: it answers a name with its own address and sends you to itself – the network notices nothing.'],['why the firewall misses it','the connection to the returned address looks perfectly normal – right protocol, port and rule.'],['the certificate as a rescue','the attacker has no valid HTTPS certificate for that name – so never click through the warning.']]);}
function mountC16Rogue(){c16Mount('q16n',[
  {glow:c16g('pc','--green')+c16g('res','--green'),dyn:c16pkt('M 64 124 L 196 124','--green')+c16lbl(160,90,'the client never verifies the answer','--green'),cap:'The whole course assumed <b>the resolver tells the truth</b>. The client has no way to verify the answer – it just gets one and trusts it.'},
  {glow:c16g('res','--red'),dyn:c16lbl(160,264,'rogue resolver: answers with the attacker’s address','--red'),cap:'A <b>rogue DNS</b>: the attacker slips you a resolver or takes over yours – and answers the name with <b>its own address</b>.'},
  {glow:c16g('pc','--red')+c16g('res','--red')+c16g('net','--red')+c16g('evil','--red'),dyn:c16pkt('M 64 124 L 330 124 L 196 198','--red')+c16lbl(330,264,'the connection looks normal – the firewall is silent','--red'),cap:'You connect to the <b>attacker</b> – and neither network nor firewall sees anything odd. Right protocol, port, allowed rule. Just a different target (the technical name: DNS hijacking).'},
  {glow:c16g('pc','--cyan')+c16g('web','--cyan'),dyn:c16lbl(500,264,'the rescue: no valid certificate for that name','--cyan'),cap:'The <b>HTTPS certificate</b> saves you: the attacker has none valid for that name and the browser screams. Try the task <b>“Rogue DNS”</b>.'}
]);}
/* ---------- L5M2 — Poisoned cache and DNSSEC ---------- */
function renderC16Dnssec(){return c16P('q16o',
  'The rogue resolver from the last module needs the attacker to control the resolver. But there is an attack on <b>an honest resolver</b> too: <b>cache poisoning</b>. Recall lesson 1 – the resolver <b>stores</b> answers. If an attacker smuggles in a <b>single</b> forged answer, the resolver caches it and then <b>hands it out to all its users of its own accord</b> until the TTL expires. One successful forgery thus diverts an entire company. How can it even be attempted? When the resolver sends a query out, the attacker tries to <b>answer before the real authority does</b> – query and answer are unencrypted and the resolver takes <b>the first one that arrives</b> and looks right. It is a race, but races can be won. So the first defense – and the one actually deployed everywhere to this day – mainly made that race <b>much harder</b>: the resolver sends the query from a <b>random source port</b> (and randomizes the letter case of the name – the 0x20 trick), so a forgery has far more numbers to guess. The full fix, though, is not to “run faster” but to make the <b>answer verifiable</b>. That is what <b>DNSSEC</b> is for: every answer is <b>digitally signed</b> by whoever owns the record, and the resolver checks the signature before accepting and caching it. A forgery without a valid signature is simply discarded – the race is suddenly worthless. Trust is built along the same tree as the names in lesson 3: the root signs the TLD, the TLD signs the domain, the domain signs the record. Two honest notes. DNSSEC solves the answer’s <b>authenticity</b>, not <b>privacy</b> – the query is still readable to everyone along the path (that is the next module). And it is far from deployed everywhere, because it costs extra work. But the idea is clean: <b>do not trust the answer, verify the signature</b>.',
  [['cache poisoning','a single forged answer lands in the resolver, which then hands it to everyone until the TTL expires.'],['DNSSEC','the answer is digitally signed by the record’s owner; the resolver verifies it and discards forgeries.'],['signing along the tree','the root signs the TLD, the TLD the domain, the domain the record – trust follows the names’ path.']]);}
function mountC16Dnssec(){c16Mount('q16o',[
  {glow:c16g('res','--amber')+c16g('net','--amber')+c16g('auth','--amber'),dyn:c16pkt('M 196 124 L 330 124 L 452 198','--amber')+c16lbl(500,264,'an honest resolver sends a query out','--amber'),cap:'This time the resolver is <b>honest</b> and sends a query out to the authority. But query and answer are <b>unencrypted</b>.'},
  {glow:c16g('evil','--red')+c16g('net','--red')+c16g('res','--red'),dyn:c16pkt('M 196 198 L 330 124 L 196 124','--red','0.8s')+c16lbl(160,264,'the attacker answers before the real authority ⚠','--red'),cap:'The attacker tries to <b>answer first</b>, before the real authority. The resolver takes <b>the first</b> that arrives and looks right – it is a race.'},
  {glow:c16g('res','--red')+c16g('pc','--red'),dyn:c16pkt('M 196 124 L 64 124','--red')+c16lbl(160,90,'poisoned cache: everyone gets the lie','--red'),cap:'<b>Cache poisoning</b>: the resolver caches the forgery and then <b>hands it to everyone</b> until the TTL expires. One forgery diverts a whole company.'},
  {glow:c16g('auth','--green')+c16g('net','--green')+c16g('res','--green'),dyn:c16pkt('M 452 198 L 330 124 L 196 124','--green')+c16lbl(330,264,'DNSSEC: a signed answer, forgery discarded ✓','--green'),cap:'<b>DNSSEC</b>: the answer is <b>signed</b> by its owner and the resolver verifies it. A forgery without a signature is discarded – the race is worthless.'}
]);}
/* ---------- L5M3 — DoH and DoT ---------- */
function renderC16Doh(){return c16P('q16p',
  'One hole remains: DNSSEC verifies that <b>nobody changed</b> the answer, but the query is still <b>readable</b> to everyone along the path. Anyone between you and the resolver – the provider, the café Wi-Fi admin, anyone with access to the link – therefore sees <b>the list of all names you ask about</b>. The fix is obvious: <b>encrypt</b> the query. We have two forms of the same idea. <b>DoT</b> (DNS over TLS) sends DNS in its <b>own encrypted tunnel</b> on a dedicated port – it is clearly recognizable as DNS, only the contents are hidden. <b>DoH</b> (DNS over HTTPS) wraps the query in <b>plain HTTPS</b>, so on the network it looks like <b>ordinary web traffic</b> and cannot be told apart from other connections. Now the interesting part, because this is a classic case where one technology helps one party and hurts another. <b>It helps the user</b>: on a foreign network nobody sees <b>the list of names you ask for</b>, and nobody can rewrite your answers in transit. (That you then connect to that particular domain is still given away by the destination IP and by <b>SNI</b> – the server name the browser sends unencrypted when setting up HTTPS, as the course <i>Why networks exist and how data travels</i> showed. DoH hides the <b>query</b>, not your whole trail.) <b>It bothers the admin</b> twice over. First, they lose the <b>visibility</b> from lesson 2 – when a browser silently uses its own DoH resolver on the internet, the company resolver <b>never learns of</b> the queries, so internal names and malicious-domain blocking stop working. Second, because DoH looks like web traffic, <b>abuse is harder to spot</b> too – recall DNS tunneling from the course <i>Advanced security (DPI, IDS/IPS)</i> (Advanced security). The sensible answer is not to ban encryption, but to take the choice back: run <b>your own resolver with DoT/DoH</b> and point clients at it. The traffic is encrypted <b>and</b> you ask a server you deliberately trust.',
  [['DoT','DNS over TLS: the query goes in its own encrypted tunnel on a dedicated port – recognizable as DNS.'],['DoH','DNS over HTTPS: the query wrapped in ordinary HTTPS – on the network it looks like plain web traffic.'],['who it helps and who it bothers','it gives the user privacy and takes the admin’s visibility and internal names – the fix is your own DoT/DoH resolver.']]);}
function mountC16Doh(){c16Mount('q16p',[
  {glow:c16g('pc','--amber')+c16g('res','--amber')+c16g('net','--amber'),dyn:c16pkt('M 64 124 L 330 124','--amber')+c16lbl(330,264,'an unencrypted query: everyone en route sees it','--amber'),cap:'A hole remains: the query is <b>readable</b> to everyone along the path. The provider and the Wi-Fi admin see the list of names you ask about.'},
  {glow:c16g('pc','--green')+c16g('res','--green')+c16g('net','--green'),dyn:c16pkt('M 64 124 L 330 124','--green','1s')+c16lbl(160,90,'DoT/DoH: the query is encrypted','--green'),cap:'The fix: <b>encrypt</b> the query. <b>DoT</b> sends it in its own tunnel (recognizable as DNS), <b>DoH</b> wraps it in ordinary HTTPS.'},
  {glow:c16g('pc','--red')+c16g('net','--red')+c16g('res','--muted'),dyn:c16pkt('M 64 124 L 330 124','--red')+c16lbl(330,264,'the browser goes to a foreign DoH resolver on the internet ⚠','--red'),cap:'The flip side: when a browser silently uses <b>its own</b> DoH resolver outside, the company resolver never sees the queries – internal names and blocking stop working.'},
  {glow:c16g('pc','--cyan')+c16g('res','--cyan'),dyn:c16pkt('M 64 124 L 196 124','--cyan')+c16lbl(160,264,'own DoT/DoH resolver: encrypted and to yourself','--cyan'),cap:'The sensible answer: <b>your own resolver with DoT/DoH</b>, with clients pointed at it. Encrypted <b>and</b> to a server you deliberately trust.'}
]);}

